"""오늘 우리 집 — 가족 계획 공유용 Streamlit 앱.

로그인 비밀번호 해시는 Streamlit Secrets에만 두고, Supabase service-role 키로
DB에 접근합니다. 사용자별 데이터 소유권 검증은 저장 함수에서 다시 수행합니다.
"""
from __future__ import annotations

import hashlib
import hmac
import html
import re
import time
from datetime import date, datetime, time as datetime_time, timedelta
from zoneinfo import ZoneInfo

import streamlit as st
from supabase import create_client

# 고정된 가족 구성원과 허용 가능한 계획 값
FAMILY = ["아빠", "엄마", "오빠", "민영", "지영", "주영"]
ARRIVAL_OPTIONS = ["집에 있어요", "저녁에 들어가요", "오늘 안 들어가요", "미정"]
DINNER_OPTIONS = ["집에서 먹어요", "밖에서 먹어요", "아직 몰라요"]
DEFAULT_ARRIVAL = "미정"
DEFAULT_DINNER = "아직 몰라요"
KST = ZoneInfo("Asia/Seoul")
PBKDF2_ITERATIONS = 310_000
TABLE_NAME = "family_plans"

# 첨부한 원본 PNG를 그대로 내장합니다. 비율/표시를 손대지 않습니다.
SPLASH_IMAGE_B64 = ""

st.set_page_config(page_title="오늘 우리 집", page_icon="🏠", layout="centered", initial_sidebar_state="collapsed")


