show_splash_once()


def get_secret_config():
    """필수 Secrets를 읽고 누락된 항목을 안전하게 알립니다."""
    try:
        db = st.secrets["supabase"]
        users = st.secrets["users"]
        url = str(db["url"]).strip()
        service_key = str(db["service_role_key"]).strip()
        if not url or not service_key:
            raise KeyError("empty Supabase setting")
        if not all(name in users for name in FAMILY):
            raise KeyError("all six users are required")
        return url, service_key, users
    except Exception:
        st.error("앱 설정이 아직 완료되지 않았어요. Streamlit Secrets에 Supabase 접속 정보와 가족 6명의 비밀번호 해시를 등록해 주세요.")
        with st.expander("필요한 설정 형식 보기"):
            st.code(
                '[supabase]\nurl = "https://YOUR_PROJECT.supabase.co"\nservice_role_key = "YOUR_SERVICE_ROLE_KEY"\n\n'
                '[users."아빠"]\nsalt = "생성한_16바이트_랜덤_솔트의_32자리_16진수"\npassword_hash = "PBKDF2_SHA256_해시_64자리_16진수"\n'
                '# 엄마, 오빠, 민영, 지영, 주영도 같은 구조로 추가',
                language="toml",
            )
        st.stop()



def verify_password(password: str, salt_hex: str, expected_hex: str) -> bool:
    """PBKDF2-HMAC-SHA256 해시를 상수 시간 비교합니다."""
    try:
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(expected_hex)
        actual = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, PBKDF2_ITERATIONS)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False


def local_today() -> date:
    """한국 시간대의 오늘 날짜를 반환합니다."""
    return datetime.now(KST).date()


def show_login(users) -> None:
    """정해진 가족 구성원만 이름과 개인 비밀번호로 로그인합니다."""
    st.markdown('<div class="brand">🏠 오늘 우리 집</div><div class="tagline">우리 가족, 오늘은 어디에?</div>', unsafe_allow_html=True)
    st.markdown('<div class="section-title">반가워요, 누구세요?</div>', unsafe_allow_html=True)
    with st.form("login_form", clear_on_submit=False):
        selected = st.selectbox("이름", FAMILY, key="login_name")
        password = st.text_input("개인 비밀번호", type="password", autocomplete="current-password")
        submitted = st.form_submit_button("로그인", use_container_width=True)
    if submitted:
        try:
            entry = users[selected]
            ok = verify_password(password, str(entry["salt"]), str(entry["password_hash"]))
        except Exception:
            ok = False
        if ok:
            st.session_state["current_user"] = selected
            st.session_state["selected_date"] = local_today()
            st.session_state["page"] = "홈"
            st.rerun()
        st.error("이름 또는 비밀번호를 확인해 주세요.")
    st.caption("가족 구성원 전용 공간이에요. 새 계정 가입은 제공하지 않습니다.")



def make_db_client(url: str, key: str):
    """Supabase 클라이언트를 생성합니다. 서비스 키는 서버 Secrets에서만 읽습니다."""
    return create_client(url, key)


def load_day_plans(client, day: date) -> dict:
    """선택 날짜의 계획을 불러옵니다. 연결 오류는 호출부에서 별도 처리합니다."""
    result = client.table(TABLE_NAME).select("member, plan_date, arrival, dinner, note, updated_at").eq("plan_date", day.isoformat()).execute()
    records = {}
    for row in (result.data or []):
        member = row.get("member")
        if member not in FAMILY:
            raise ValueError("가족 구성원이 아닌 레코드가 DB에 있습니다.")
        if row.get("arrival") not in ARRIVAL_OPTIONS or row.get("dinner") not in DINNER_OPTIONS:
            raise ValueError("DB 계획 값이 허용된 값과 일치하지 않습니다.")
        note = row.get("note") or ""
        if not isinstance(note, str) or len(note) > 60:
            raise ValueError("DB 메모 값이 유효하지 않습니다.")
        records[member] = {"arrival": row["arrival"], "dinner": row["dinner"], "note": note}
    return records


def save_own_plan(client, actor: str, target_member: str, day: date, arrival: str, dinner: str, note: str) -> None:
    """본인 소유권과 모든 입력값을 저장 직전에 검증한 뒤 해당 키를 갱신합니다."""
    if not actor or actor not in FAMILY or target_member != actor:
        raise PermissionError("본인 계획만 저장할 수 있습니다.")
    if not isinstance(day, date):
        raise ValueError("날짜가 올바르지 않습니다.")
    if arrival not in ARRIVAL_OPTIONS or dinner not in DINNER_OPTIONS:
        raise ValueError("선택값이 올바르지 않습니다.")
    if not isinstance(note, str):
        raise ValueError("메모 형식이 올바르지 않습니다.")
    note = note.strip()
    if len(note) > 60:
        raise ValueError("메모는 60자 이내로 입력해 주세요.")
    payload = {
        "member": actor,
        "plan_date": day.isoformat(),
        "arrival": arrival,
        "dinner": dinner,
        "note": note,
        "updated_at": datetime.now(KST).isoformat(),
    }
    # (날짜, 가족 구성원) 유일 키를 기준으로 중복 없이 기존 기록을 갱신합니다.
    client.table(TABLE_NAME).upsert(payload, on_conflict="plan_date,member").execute()


