def safe_text(value: str) -> str:
    """HTML 카드에 출력하기 전 텍스트를 이스케이프합니다."""
    return html.escape(str(value), quote=True)


def render_family_cards(plans: dict, current_user: str) -> None:
    """가족 6명을 고정 순서의 3열 × 2행 카드로 표시합니다."""
    colors = ["#f7d36a", "#a9dfcf", "#f4b9a7", "#c9b9ed", "#acd77a", "#f2c0d4"]
    faces = ["👨🏻", "👩🏻", "🧑🏻", "👧🏻", "👧🏻", "👦🏻"]
    for start in (0, 3):
        cols = st.columns(3, gap="small")
        for i, member in enumerate(FAMILY[start:start + 3]):
            plan = plans.get(member, {"arrival": DEFAULT_ARRIVAL, "dinner": DEFAULT_DINNER, "note": ""})
            badge = '<span class="me-badge">나</span>' if member == current_user else ""
            note_html = f'<div class="memo-line">💬 {safe_text(plan["note"])}</div>' if plan["note"] else '<div class="memo-line">&nbsp;</div>'
            card = (
                '<div class="plan-card">'
                f'<div class="avatar" style="background:{colors[start+i]}">{faces[start+i]}</div>'
                f'<div class="person-name">{safe_text(member)}{badge}</div>'
                f'<div class="plan-line">🏠 {safe_text(plan["arrival"])}</div>'
                f'<div class="plan-line">🍚 {safe_text(plan["dinner"])}</div>'
                f'{note_html}</div>'
            )
            with cols[i]:
                st.markdown(card, unsafe_allow_html=True)


def render_summary(plans: dict) -> None:
    """선택한 날짜의 입력된 계획만으로 네 가지 인원 수를 계산합니다."""
    people = [plans.get(member, {"arrival": DEFAULT_ARRIVAL, "dinner": DEFAULT_DINNER}) for member in FAMILY]
    counts = [
        sum(p["arrival"] in ("집에 있어요", "저녁에 들어가요") for p in people),
        sum(p["dinner"] == "집에서 먹어요" for p in people),
        sum(p["arrival"] == DEFAULT_ARRIVAL for p in people),
        sum(p["dinner"] == DEFAULT_DINNER for p in people),
    ]
    labels = ["집에 있을 예정", "집에서 저녁", "귀가 미정", "식사 미정"]
    cols = st.columns(4, gap="small")
    for col, number, label in zip(cols, counts, labels):
        with col:
            st.markdown(f'<div class="summary-card"><div class="summary-num">{number}</div><div class="summary-label">{label}</div></div>', unsafe_allow_html=True)
    st.markdown('<div class="muted" style="margin-top:7px">실제 위치가 아니라 가족이 입력한 계획 기준이에요.</div>', unsafe_allow_html=True)


def render_memos(plans: dict) -> None:
    """선택 날짜의 비어 있지 않은 가족 개인 메모를 모아 표시합니다."""
    entries = [(member, plans.get(member, {}).get("note", "")) for member in FAMILY]
    entries = [(member, note.strip()) for member, note in entries if note and note.strip()]
    if not entries:
        st.markdown('<div class="memo-card"><div class="memo-text">오늘 함께 나눌 말을 남겨보세요.</div></div>', unsafe_allow_html=True)
        return
    for member, note in entries:
        st.markdown(
            f'<div class="memo-card"><div class="memo-author">💬 {safe_text(member)}</div><div class="memo-text">{safe_text(note)}</div></div>',
            unsafe_allow_html=True,
        )


def render_plan_editor(client, current_user: str, day: date, plans: dict) -> None:
    """현재 사용자 계획 편집기. 귀가·식사는 독립된 선택 필드입니다."""
    own = plans.get(current_user, {"arrival": DEFAULT_ARRIVAL, "dinner": DEFAULT_DINNER, "note": ""})
    st.markdown('<div class="section-title">내 하루</div>', unsafe_allow_html=True)
    tiles = st.columns(2, gap="small")
    with tiles[0]:
        st.markdown('<div class="tile tile-home"><span class="tile-icon">🏠</span>귀가 계획</div>', unsafe_allow_html=True)
    with tiles[1]:
        st.markdown('<div class="tile tile-dinner"><span class="tile-icon">🍚</span>저녁 식사</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="muted" style="margin:8px 0 10px">현재 선택: {safe_text(own["arrival"])} · {safe_text(own["dinner"])}</div>', unsafe_allow_html=True)
    with st.form(f"plan_form_{day.isoformat()}"):
        c1, c2 = st.columns(2, gap="small")
        with c1:
            arrival = st.selectbox("귀가 계획", ARRIVAL_OPTIONS, index=ARRIVAL_OPTIONS.index(own["arrival"]), key=f"arrival_{day.isoformat()}")
        with c2:
            dinner = st.selectbox("저녁 식사 계획", DINNER_OPTIONS, index=DINNER_OPTIONS.index(own["dinner"]), key=f"dinner_{day.isoformat()}")
        note = st.text_input("개인 한 줄 메모 (선택, 최대 60자)", value=own["note"], max_chars=60, key=f"note_{day.isoformat()}", help="메모를 비우고 저장하면 본인 메모가 삭제됩니다.")
        submitted = st.form_submit_button("내 계획 저장", use_container_width=True)
    if submitted:
        try:
            save_own_plan(client, current_user, current_user, day, arrival, dinner, note)
            st.session_state["save_notice"] = "계획을 공유했어요. 바뀌면 언제든 수정해요."
            st.rerun()
        except PermissionError:
            st.error("본인 계획만 저장할 수 있어요.")
        except ValueError as exc:
            st.error(str(exc))
        except Exception:
            st.error("계획을 저장하지 못했어요. 잠시 후 다시 시도해 주세요.")


def upcoming_weekend(start: date) -> tuple[date, date]:
    """오늘부터 가장 가까운 토요일과 그 다음 날인 일요일을 반환합니다."""
    days_until_saturday = (5 - start.weekday()) % 7
    saturday = start + timedelta(days=days_until_saturday)
    return saturday, saturday + timedelta(days=1)


def fmt_date(day: date) -> str:
    """한국어 날짜와 요일을 표시합니다."""
    weekdays = ["월", "화", "수", "목", "금", "토", "일"]
    return f"{day.month}월 {day.day}일 ({weekdays[day.weekday()]})"


def render_nav() -> None:
    """화면 하단의 앱형 메뉴를 표시합니다. 본문 하단에 안전 여백이 있습니다."""
    st.markdown('<div style="height:18px"></div>', unsafe_allow_html=True)
    st.markdown('<div class="muted" style="text-align:center;margin-bottom:7px">오늘 우리 집 · 가족 계획 게시판</div>', unsafe_allow_html=True)
    current = st.session_state.get("page", "홈")
    cols = st.columns(3, gap="small")
    for col, label, icon in zip(cols, ["홈", "주말", "메모"], ["🏠", "☀️", "💬"]):
        with col:
            if st.button(f"{icon}  {label}", key=f"nav_{label}", use_container_width=True, type="primary" if current == label else "secondary"):
                st.session_state["page"] = label
                st.rerun()


def main() -> None:
    """앱 진입점: 설정, 로그인, DB 조회, 각 화면을 순서대로 구성합니다."""
    inject_app_css()
    url, service_key, users = get_secret_config()
    if not st.session_state.get("current_user"):
        show_login(users)
        return
    current_user = st.session_state["current_user"]
    if current_user not in FAMILY:
        st.session_state.pop("current_user", None)
        st.rerun()
    if "selected_date" not in st.session_state:
        st.session_state["selected_date"] = local_today()
    if "page" not in st.session_state:
        st.session_state["page"] = "홈"

    with st.spinner("가족 계획을 불러오고 있어요…"):
        try:
            client = make_db_client(url, service_key)
            # 화면별 날짜를 결정한 뒤 최신 데이터를 다시 조회합니다.
            page = st.session_state.get("page", "홈")
            if page == "주말":
                sat, sun = upcoming_weekend(local_today())
                weekend_day = st.session_state.get("weekend_day", "토요일")
                day = sat if weekend_day == "토요일" else sun
                st.session_state["selected_date"] = day
            else:
                day = st.session_state["selected_date"]
            plans = load_day_plans(client, day)
        except Exception:
            st.error("가족 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요.")
            if st.button("다시 시도", use_container_width=True):
                st.rerun()
            st.stop()

    st.markdown('<div class="brand">🏠 오늘 우리 집</div><div class="tagline">우리 가족, 오늘은 어디에?</div>', unsafe_allow_html=True)
    if st.session_state.get("save_notice"):
        st.success(st.session_state.pop("save_notice"))
    top_left, top_right = st.columns([2, 1])
    with top_left:
        st.markdown(f'<span class="user-pill">{safe_text(current_user)}님 로그인 중</span>', unsafe_allow_html=True)
    with top_right:
        if st.button("최신 계획 불러오기", key="refresh_plans", use_container_width=True):
            st.rerun()
    if st.button("로그아웃", key="logout", help="현재 계정에서 로그아웃합니다."):
        st.session_state.pop("current_user", None)
        st.session_state["page"] = "홈"
        st.rerun()

    page = st.session_state.get("page", "홈")
    if page == "주말":
        sat, sun = upcoming_weekend(local_today())
        st.markdown('<div class="section-title">다가오는 주말</div>', unsafe_allow_html=True)
        b1, b2 = st.columns(2, gap="small")
        with b1:
            if st.button(f"토요일 · {fmt_date(sat)}", key="choose_saturday", use_container_width=True, type="primary" if st.session_state.get("weekend_day", "토요일") == "토요일" else "secondary"):
                st.session_state["weekend_day"] = "토요일"
                st.session_state["selected_date"] = sat
                st.rerun()
        with b2:
            if st.button(f"일요일 · {fmt_date(sun)}", key="choose_sunday", use_container_width=True, type="primary" if st.session_state.get("weekend_day", "토요일") == "일요일" else "secondary"):
                st.session_state["weekend_day"] = "일요일"
                st.session_state["selected_date"] = sun
                st.rerun()
        day = sat if st.session_state.get("weekend_day", "토요일") == "토요일" else sun
        # 페이지 전환 직후에는 DB 조회가 이전 날짜일 수 있어 날짜 상태를 맞추고 재조회합니다.
        if st.session_state.get("selected_date") != day:
            st.session_state["selected_date"] = day
            st.rerun()
        plans = load_day_plans(client, day)
    elif page == "메모":
        st.markdown('<div class="section-title">가족 메모</div>', unsafe_allow_html=True)
        changed_date = st.date_input("날짜 선택", value=st.session_state["selected_date"], key="memo_date")
        if changed_date != st.session_state["selected_date"]:
            st.session_state["selected_date"] = changed_date
            st.rerun()
        day = changed_date
        plans = load_day_plans(client, day)
    else:
        # 빠른 날짜 선택 버튼은 날짜 입력 위젯보다 먼저 렌더링해 상태를 안전하게 갱신합니다.
        d1, d2, d3 = st.columns([1, 1, 2], gap="small")
        today = local_today()
        with d1:
            if st.button("오늘", key="quick_today", use_container_width=True):
                st.session_state["selected_date"] = today
                st.session_state["home_date"] = today
                st.rerun()
        with d2:
            if st.button("내일", key="quick_tomorrow", use_container_width=True):
                tomorrow = today + timedelta(days=1)
                st.session_state["selected_date"] = tomorrow
                st.session_state["home_date"] = tomorrow
                st.rerun()
        with d3:
            chosen = st.date_input("날짜 선택", value=st.session_state.get("home_date", st.session_state["selected_date"]), key="home_date")
        if chosen != st.session_state["selected_date"]:
            st.session_state["selected_date"] = chosen
            st.rerun()
        day = chosen
        if day == today:
            date_label = f"오늘 · {fmt_date(day)}"
        elif day == today + timedelta(days=1):
            date_label = f"내일 · {fmt_date(day)}"
        else:
            date_label = fmt_date(day)
        st.markdown(f'<div class="section-title">{safe_text(date_label)}</div>', unsafe_allow_html=True)

    if page != "메모":
        render_plan_editor(client, current_user, day, plans)
        st.markdown('<div class="section-title">우리 가족</div>', unsafe_allow_html=True)
        render_family_cards(plans, current_user)
        st.markdown('<div class="section-title">오늘의 인원</div>', unsafe_allow_html=True)
        render_summary(plans)
    st.markdown('<div class="section-title">가족 메모 모아보기</div>', unsafe_allow_html=True)
    render_memos(plans)
    render_nav()


if __name__ == "__main__":
    main()
